class Configuration {
    const int required_id;      // Must be initialized in list
    std::string user_name;
    double version;

    // Use the member initializer list for efficiency
    Configuration(int id, const std::string& name)
        : required_id(id),      // Direct initialization (no default construction)
          user_name(name),      // Efficiency: Direct construction
          version(1.0)
    {
        // Body is empty: avoids assignment after construction
    }
};
